gold_flashcards_json:
[
  {
    "front": "Classical P(E)?",
    "back": "Favourable / total outcomes."
  },
  {
    "front": "Addition rule?",
    "back": "P(A∪B)=P(A)+P(B)-P(A∩B)"
  },
  {
    "front": "Independent events?",
    "back": "P(A∩B)=P(A)P(B)"
  },
  {
    "front": "Bayes links?",
    "back": "Prior, likelihood → posterior"
  },
  {
    "front": "Complement?",
    "back": "P(A')=1-P(A)"
  }
]

